import {chromium} from 'playwright';import fs from 'node:fs/promises';import assert from 'node:assert/strict';const candidates={"hk-nobel-08-hassabis-illustrated-v1":{"id":"hk-nobel-08-hassabis-illustrated-v1","createdAt":"2026-11-04T00:00:00.000Z","stage":{"id":"hk-nobel-08-hassabis-illustrated-v1","name":"諾貝爾科學故事 08：哈薩比斯與蛋白質預測（廣東話）","description":"從遊戲到生命科學，認識人工智能如何幫助研究蛋白質，與日常生活有甚麼關係。","languageDirective":"使用香港繁體中文，以廣東話向初中學生講授。明確區分計算預測、實驗證據和仍待驗證的應用；不提供醫療建議。","createdAt":1793793600000,"updatedAt":1793793600000,"style":"slide","generatedAgentConfigs":[{"id":"nobel08-teacher","name":"科學故事老師","role":"teacher","persona":"我用香港生活例子講解蛋白質結構預測及其價值，說明類比限制，不把研究前景說成已有療效。","avatar":"/avatars/teacher.png","color":"#24665f","priority":10},{"id":"nobel08-assistant","name":"科學小助手","role":"assistant","persona":"我幫學生區分計算模型、實驗證據和研究前景，尊重不確定性，不提供個人診療。","avatar":"/avatars/assist.png","color":"#2563eb","priority":7},{"id":"nobel08-student","name":"好奇同學","role":"student","persona":"我是AI同學，喜歡提出簡短問題，幫助大家思考如何檢查證據。","avatar":"/avatars/curious.png","color":"#bf9949","priority":5}]},"scenes":[{"id":"nobel08-slide-01","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"德米斯・哈薩比斯","order":1,"outlineId":"nobel08-slide-01-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"interactive","actions":[{"id":"nobel08-slide-01-speech","type":"speech","text":"相入面呢位科學家叫德米斯・哈薩比斯，係二零二四年諾貝爾化學獎共同得主。佢參與過遊戲開發，讀過電腦科學，亦接受過腦科學研究訓練。今日我哋跟住佢問一個問題：電腦可唔可以幫科學家預測生命入面細小工具嘅形狀？","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-01.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-01.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>*{box-sizing:border-box}html,body{margin:0;background:#f6f1e6;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}.slide{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden}.background{display:block;width:100%;height:100%;object-fit:fill}.portrait{position:absolute;left:68.6%;top:17.8%;width:22.5%;height:51.4%;object-fit:contain}.caption{position:absolute;left:62%;top:71%;width:34.5%;color:#31515a;font-size:clamp(10px,1vw,13px);line-height:1.25}.voice{position:absolute;left:62%;top:85%;font-size:clamp(15px,1.5vw,20px)}.footer{position:absolute;left:4%;bottom:1.5%;width:92%;padding:.4%;background:#f5f0e8;color:#31515a;font-size:clamp(10px,1vw,13px)}.mobile-title{display:none}a{color:#24665f}html.phone .background{opacity:.14}html.phone .mobile-title{display:block;position:absolute;left:4%;top:5%;width:59%;font-size:60px;line-height:1.15;font-weight:800}html.phone .mobile-title span{display:block;font-size:46px;margin-top:16px}html.phone .portrait{left:68%;top:6%;width:27%;height:56%}html.phone .caption{display:none}.mobile-credit{display:none}html.phone .mobile-credit{display:block;position:absolute;left:4%;top:63%;width:58%;font-size:38px;line-height:1.15;color:#31515a}html.phone .voice{left:64%;top:73%;font-size:50px;font-weight:700}html.phone .footer{font-size:25px}</style><script>if(Math.min(screen.width,screen.height)<=500)document.documentElement.classList.add('phone')</script><div class=\"slide\"><img class=\"background\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/01-zh-Hant.png\" alt=\"德米斯・哈薩比斯：從遊戲世界，到研究生命的小工具。2024年諾貝爾化學獎共同得主。\"><div class=\"mobile-title\">德米斯・哈薩比斯<span>從遊戲世界，到研究生命的小工具<br>2024年諾貝爾化學獎共同得主</span></div><img class=\"portrait\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/hassabis-portrait.jpg\" alt=\"德米斯・哈薩比斯資料肖像\"><div class=\"caption\">德米斯・哈薩比斯，2018年資料照。The Royal Society，經裁剪，<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://commons.wikimedia.org/wiki/File:Demis_Hassabis_Royal_Society_(cropped).jpg\">來源及授權</a>（CC BY-SA 4.0／原圖 CC BY-SA 3.0）。</div><div class=\"mobile-credit\">肖像：The Royal Society，2018，經裁剪<br><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://commons.wikimedia.org/wiki/File:Demis_Hassabis_Royal_Society_(cropped).jpg\">來源及授權</a>：CC BY-SA 4.0／原圖 3.0</div><a class=\"voice\" href=\"/classroom/hk-nobel-08-hassabis-illustrated-v1-mandarin\" target=\"_blank\" rel=\"noopener noreferrer\">切換至普通話講解 →</a><div class=\"footer\">教學插畫為示意，並非研究現場。 <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></div></div></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel08-slide-02","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"同一張紙，形狀改變了甚麼？","order":2,"outlineId":"nobel08-slide-02-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"interactive","actions":[{"id":"nobel08-slide-02-speech","type":"speech","text":"想像枱上面有幾枚萬字夾。平放一張紙，萬字夾容易滑走；摺成合適嘅小紙盒，就方便裝住佢哋。形狀改變，用途亦可能唔同。呢個只係講形狀重要嘅比喻；蛋白質唔係俾小人摺出嚟嘅紙盒。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-02.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-02.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>html,body{margin:0;background:#f5f0e8;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}main{max-width:1080px;margin:auto;padding:12px 20px}.art{display:block;width:100%;max-height:47vh;object-fit:contain}.question{border:2px solid #b5d4c5;background:#fffaf0;border-radius:18px;padding:14px 20px}h2{font-size:clamp(18px,2.3vw,27px);margin:0 0 10px}.options{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;font-size:clamp(16px,1.7vw,22px);border:2px solid #368471;border-radius:10px;padding:10px 16px;background:#fff}button[aria-pressed=true]{background:#b5e5cf}.feedback{font-size:17px;line-height:1.5;min-height:2em}.note{font-size:13px;color:#47616c}html.phone .art{max-height:8vh}html.phone .question{padding:8px 14px}html.phone h2{font-size:52px}html.phone button{font-size:56px;padding:40px 28px}html.phone .feedback{font-size:40px;margin:8px 0;min-height:0}html.phone .note{font-size:50px;margin:3px 0}</style><script>if(Math.min(screen.width,screen.height)<=500)document.documentElement.classList.add('phone')</script><main><img class=\"art\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/02-zh-Hant.png\" alt=\"一張紙與摺成的紙盒，用來比喻形狀與用途的關係\"><section class=\"question\"><h2>要用紙盛載萬字夾，哪一種形狀通常比較方便？</h2><div class=\"options\"><button data-choice=\"0\" aria-pressed=\"false\">平放的紙</button><button data-choice=\"1\" aria-pressed=\"false\">摺成合適的小紙盒</button></div><p class=\"feedback\" id=\"feedback\" aria-live=\"polite\"></p></section><p class=\"note\">生活類比：形狀可能影響用途；蛋白質不是紙盒。可以重新選擇。</p></main><script>document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('feedback').textContent=b.dataset.choice==='1'?'對，合適的小紙盒較容易盛載。形狀有時影響用途，蛋白質則不是紙盒。':'平放的紙較難擋住萬字夾滑落；試試另一種形狀。這只是生活類比。'})</script></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel08-slide-03","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"身體裏的小工具","order":3,"outlineId":"nobel08-slide-03-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-03-focus","type":"spotlight","elementId":"nobel08-slide-03-key"},{"id":"nobel08-slide-03-speech","type":"speech","text":"你可能喺牛奶包裝上見過蛋白質呢個詞。身體入面有好多唔同蛋白質：有啲幫助化學反應，有啲參與傳遞訊號。佢哋唔係同一款零件。想研究佢哋點樣工作，形狀係其中一條重要線索。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-03.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-03.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-03-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-03-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/03-zh-Hant.png","name":"身體裏的小工具；許多蛋白質參與身體的不同工作。"},{"type":"shape","id":"nobel08-slide-03-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-03-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-03-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"你可能喺牛奶包裝上見過蛋白質呢個詞。身體入面有好多唔同蛋白質：有啲幫助化學反應，有啲參與傳遞訊號。佢哋唔係同一款零件。想研究佢哋點樣工作，形狀係其中一條重要線索。"},"script":"你可能喺牛奶包裝上見過蛋白質呢個詞。身體入面有好多唔同蛋白質：有啲幫助化學反應，有啲參與傳遞訊號。佢哋唔係同一款零件。想研究佢哋點樣工作，形狀係其中一條重要線索。"}},{"id":"nobel08-slide-04","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"順序表，還不是立體圖","order":4,"outlineId":"nobel08-slide-04-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-04-focus","type":"spotlight","elementId":"nobel08-slide-04-key"},{"id":"nobel08-slide-04-speech","type":"speech","text":"好多蛋白質可以想像成由小零件連起來嘅鏈。科學家用字母記錄零件嘅次序；但一串字母，唔等於直接見到條鏈喺空間點樣彎曲。順序表提供線索，立體模型就幫手研究各部分嘅空間關係。真實蛋白質會受環境影響，亦可能活動。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-04.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-04.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-04-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-04-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/04-zh-Hant.png","name":"順序表，還不是立體圖；知道小零件的順序，還要研究它在空間的形狀。"},{"type":"shape","id":"nobel08-slide-04-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-04-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-04-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"好多蛋白質可以想像成由小零件連起來嘅鏈。科學家用字母記錄零件嘅次序；但一串字母，唔等於直接見到條鏈喺空間點樣彎曲。順序表提供線索，立體模型就幫手研究各部分嘅空間關係。真實蛋白質會受環境影響，亦可能活動。"},"script":"好多蛋白質可以想像成由小零件連起來嘅鏈。科學家用字母記錄零件嘅次序；但一串字母，唔等於直接見到條鏈喺空間點樣彎曲。順序表提供線索，立體模型就幫手研究各部分嘅空間關係。真實蛋白質會受環境影響，亦可能活動。"}},{"id":"nobel08-slide-05","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"為甚麼他想研究這個難題？","order":5,"outlineId":"nobel08-slide-05-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-05-focus","type":"spotlight","elementId":"nobel08-slide-05-key"},{"id":"nobel08-slide-05-speech","type":"speech","text":"哈薩比斯喺回顧中講過，人工智能喺棋盤取得進展之後，佢希望將技術用於加快科學發現。團隊揀咗蛋白質形狀預測呢個難題。下棋同預測蛋白質唔係同一個系統，需要重新設計方法，同唔同專業嘅人合作。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-05.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-05.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-05-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-05-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/05-zh-Hant.png","name":"為甚麼他想研究這個難題？；將人工智能帶到科學問題，需要不同專業合作。"},{"type":"shape","id":"nobel08-slide-05-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-05-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-05-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"哈薩比斯喺回顧中講過，人工智能喺棋盤取得進展之後，佢希望將技術用於加快科學發現。團隊揀咗蛋白質形狀預測呢個難題。下棋同預測蛋白質唔係同一個系統，需要重新設計方法，同唔同專業嘅人合作。"},"script":"哈薩比斯喺回顧中講過，人工智能喺棋盤取得進展之後，佢希望將技術用於加快科學發現。團隊揀咗蛋白質形狀預測呢個難題。下棋同預測蛋白質唔係同一個系統，需要重新設計方法，同唔同專業嘅人合作。"}},{"id":"nobel08-slide-06","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"AI 幫忙做甚麼？","order":6,"outlineId":"nobel08-slide-06-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-06-focus","type":"spotlight","elementId":"nobel08-slide-06-key"},{"id":"nobel08-slide-06-speech","type":"speech","text":"以往研究者用實驗積累咗好多蛋白質結構資料，成為人工智能學習嘅重要基礎。哈薩比斯、約翰・江珀同團隊開發嘅 AlphaFold，利用蛋白質嘅序列等線索預測結構。電腦冇走入細胞影相；結果係一個可以再檢查嘅計算模型。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-06.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-06.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-06-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-06-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/06-zh-Hant.png","name":"AI 幫忙做甚麼？；利用已知資料與序列等線索，預測蛋白質的形狀。"},{"type":"shape","id":"nobel08-slide-06-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-06-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-06-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"以往研究者用實驗積累咗好多蛋白質結構資料，成為人工智能學習嘅重要基礎。哈薩比斯、約翰・江珀同團隊開發嘅 AlphaFold，利用蛋白質嘅序列等線索預測結構。電腦冇走入細胞影相；結果係一個可以再檢查嘅計算模型。"},"script":"以往研究者用實驗積累咗好多蛋白質結構資料，成為人工智能學習嘅重要基礎。哈薩比斯、約翰・江珀同團隊開發嘅 AlphaFold，利用蛋白質嘅序列等線索預測結構。電腦冇走入細胞影相；結果係一個可以再檢查嘅計算模型。"}},{"id":"nobel08-slide-07","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"怎樣知道預測不是瞎猜？","order":7,"outlineId":"nobel08-slide-07-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"interactive","actions":[{"id":"nobel08-slide-07-speech","type":"speech","text":"畫得靚，點知唔係亂估？喺一次重要評估，研究者先交預測，再同未公開嘅實驗結構比較。二零二零年 AlphaFold 二喺評估中取得重要進展。右邊係論文圖中一個例子：藍色係預測，綠色係根據實驗得出嘅模型。呢個唔係顯微鏡相片，亦唔代表每次預測都一樣準。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-07.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-07.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>*{box-sizing:border-box}html,body{margin:0;background:#f6f1e6;font-family:system-ui,\"PingFang HK\",sans-serif}.slide{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden}.background{display:block;width:100%;height:100%;object-fit:fill}.figure{position:absolute;left:61%;top:27%;width:31.5%;height:44.8%;overflow:hidden;background:white}.figure img{position:absolute;max-width:none;width:406.981%;height:auto;left:-102.83%;top:-21.176%}.caption{position:absolute;left:61%;top:74%;width:34%;color:#31515a;font-size:clamp(8px,1.1vw,14px);line-height:1.3}.footer{position:absolute;left:4%;bottom:1.5%;width:92%;padding:.4%;background:#f5f0e8;color:#31515a;font-size:clamp(8px,1vw,13px)}a{color:#245f5a}.mobile-heading{display:none}html.phone .background{opacity:.13}html.phone .mobile-heading{display:block;position:absolute;left:4%;top:8%;width:38%;font-size:58px;font-weight:800;line-height:1.25;color:#102b38}html.phone .figure{left:56%;top:4%;width:40%;height:57%}html.phone .caption{left:4%;top:66%;width:92%;font-size:50px;line-height:1.1}html.phone .footer{display:none}</style><script>if(Math.min(screen.width,screen.height)<=500)document.documentElement.classList.add('phone')</script><div class=\"slide\"><img class=\"background\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/07-zh-Hant.png\" alt=\"怎樣知道預測不是瞎猜？先交預測，再和實驗得到的結構比較。\"><div class=\"mobile-heading\">怎樣知道預測不是瞎猜？</div><div class=\"figure\"><img src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/alphafold-paper-figure-1.png\" alt=\"論文圖1b局部，藍色預測與綠色實驗結構模型的對照\"></div><div class=\"caption\">藍：預測；綠：實驗模型。不是照片。Jumper 等，Nature（2021）圖1b；<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nature.com/articles/s41586-021-03819-2\">論文及完整圖</a>／<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>。</div><div class=\"footer\">教學插畫為示意，並非研究現場。 <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></div></div></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel08-slide-08","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"為甚麼值得諾貝爾獎？","order":8,"outlineId":"nobel08-slide-08-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-08-focus","type":"spotlight","elementId":"nobel08-slide-08-key"},{"id":"nobel08-slide-08-speech","type":"speech","text":"蛋白質結構預測係科學家面對咗好多年嘅難題。哈薩比斯、江珀同團隊嘅進展，畀研究者多咗重要工具去探索結構。佢哋因此共同獲得二零二四年諾貝爾化學獎一部分；同年戴維・貝克因計算設計蛋白質獲得另一部分。預測已有蛋白質，同設計新蛋白質，係有關但唔一樣嘅工作。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-08.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-08.mp3"},{"id":"nobel08-slide-08-discussion","type":"discussion","agentId":"nobel08-assistant","topic":"蛋白質結構預測為甚麼有價值？我們還需要怎樣檢查？","prompt":"簡短課堂討論。科學小助手先解釋預測模型不等於實驗照片；科學故事老師連回研究工具的價值；AI同學提出一個與證據有關的追問。各人只說自己的話，然後交回學生，不延伸新回合。不提供個人醫療建議。"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-08-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-08-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/08-zh-Hant.png","name":"為甚麼值得諾貝爾獎？；研究者多了一種探索蛋白質結構的重要工具。"},{"type":"shape","id":"nobel08-slide-08-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-08-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-08-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"蛋白質結構預測係科學家面對咗好多年嘅難題。哈薩比斯、江珀同團隊嘅進展，畀研究者多咗重要工具去探索結構。佢哋因此共同獲得二零二四年諾貝爾化學獎一部分；同年戴維・貝克因計算設計蛋白質獲得另一部分。預測已有蛋白質，同設計新蛋白質，係有關但唔一樣嘅工作。"},"script":"蛋白質結構預測係科學家面對咗好多年嘅難題。哈薩比斯、江珀同團隊嘅進展，畀研究者多咗重要工具去探索結構。佢哋因此共同獲得二零二四年諾貝爾化學獎一部分；同年戴維・貝克因計算設計蛋白質獲得另一部分。預測已有蛋白質，同設計新蛋白質，係有關但唔一樣嘅工作。"}},{"id":"nobel08-slide-09","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"飲料瓶與科學有甚麼關係？","order":9,"outlineId":"nobel08-slide-09-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-09-focus","type":"spotlight","elementId":"nobel08-slide-09-key"},{"id":"nobel08-slide-09-speech","type":"speech","text":"我哋每日都會接觸塑膠包裝。研究者正研究可以幫助分解某啲塑膠嘅酶；許多酶係幫助化學反應嘅蛋白質。形狀線索有機會幫研究者提出問題，再用實驗檢查。但呢個唔等於所有塑膠而家都可以輕易消失；材料、條件同效果都要分別驗證。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-09.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-09.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-09-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-09-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/09-zh-Hant.png","name":"飲料瓶與科學有甚麼關係？；研究某些酶的形狀，可能幫助科學家研究材料處理。"},{"type":"shape","id":"nobel08-slide-09-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-09-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-09-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"我哋每日都會接觸塑膠包裝。研究者正研究可以幫助分解某啲塑膠嘅酶；許多酶係幫助化學反應嘅蛋白質。形狀線索有機會幫研究者提出問題，再用實驗檢查。但呢個唔等於所有塑膠而家都可以輕易消失；材料、條件同效果都要分別驗證。"},"script":"我哋每日都會接觸塑膠包裝。研究者正研究可以幫助分解某啲塑膠嘅酶；許多酶係幫助化學反應嘅蛋白質。形狀線索有機會幫研究者提出問題，再用實驗檢查。但呢個唔等於所有塑膠而家都可以輕易消失；材料、條件同效果都要分別驗證。"}},{"id":"nobel08-slide-10","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"離新藥，還有多遠？","order":10,"outlineId":"nobel08-slide-10-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-10-focus","type":"spotlight","elementId":"nobel08-slide-10-key"},{"id":"nobel08-slide-10-speech","type":"speech","text":"我哋希望更了解疾病，將來有安全有效嘅治療。結構預測可以畀研究者新線索，幫佢哋決定做乜實驗。但由一個模型到真正嘅藥，中間仲需要好多安全同效果檢驗。重要嘅係多咗一種研究工具，唔係保證即刻有新藥。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-10.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-10.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-10-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-10-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/10-zh-Hant.png","name":"離新藥，還有多遠？；預測提供研究線索；安全和效果仍要經過檢驗。"},{"type":"shape","id":"nobel08-slide-10-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-10-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-10-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"我哋希望更了解疾病，將來有安全有效嘅治療。結構預測可以畀研究者新線索，幫佢哋決定做乜實驗。但由一個模型到真正嘅藥，中間仲需要好多安全同效果檢驗。重要嘅係多咗一種研究工具，唔係保證即刻有新藥。"},"script":"我哋希望更了解疾病，將來有安全有效嘅治療。結構預測可以畀研究者新線索，幫佢哋決定做乜實驗。但由一個模型到真正嘅藥，中間仲需要好多安全同效果檢驗。重要嘅係多咗一種研究工具，唔係保證即刻有新藥。"}},{"id":"nobel08-slide-11","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"三次小判斷","order":11,"outlineId":"nobel08-slide-11-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"quiz","actions":[{"id":"nobel08-slide-11-speech","type":"speech","text":"而家停一停，試下判斷三個問題。答錯可以睇解釋，再試一次。唔使背術語，重點係分清楚順序、預測同證據。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-11.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-11.mp3"}],"content":{"type":"quiz","questions":[{"id":"nobel08-slide-11-q1","type":"single","question":"1. 只知道蛋白質小零件的連接順序，是否就已直接看到完整立體形狀？","options":[{"value":"A","label":"是，順序表就是立體圖"},{"value":"B","label":"還需要進一步研究或預測"}],"answer":["B"],"analysis":"A：順序提供線索，但順序表和立體圖不同。；B：正確，還需要研究或預測空間關係。","points":10,"hasAnswer":true},{"id":"nobel08-slide-11-q2","type":"single","question":"2. AI 給出結構預測圖，是否等於拍了一張分子照片？","options":[{"value":"A","label":"是，圖漂亮就是實拍"},{"value":"B","label":"不是，它是需要檢查的模型"}],"answer":["B"],"analysis":"A：圖漂亮不代表實拍。；B：正確，這是計算預測，需要查核與評估不確定性。","points":10,"hasAnswer":true},{"id":"nobel08-slide-11-q3","type":"single","question":"3. 一項研究為尋找新藥提供線索，接下來可以怎樣說？","options":[{"value":"A","label":"已證明某種藥可以治病"},{"value":"B","label":"有了可繼續檢驗的方向"}],"answer":["B"],"analysis":"A：研究線索並不是療效證明。；B：正確，是否安全有效仍需後續研究。","points":10,"hasAnswer":true}]}},{"id":"nobel08-slide-12","stageId":"hk-nobel-08-hassabis-illustrated-v1","title":"一個好問題，帶來更多問題","order":12,"outlineId":"nobel08-slide-12-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-12-focus","type":"spotlight","elementId":"nobel08-slide-12-key"},{"id":"nobel08-slide-12-speech","type":"speech","text":"哈薩比斯嘅故事連結咗遊戲開發、不同學科嘅學習同團隊合作。獲獎進展幫更多研究者探索生命入面嘅小工具。下次見到人工智能畀出漂亮答案，可以問：根據係乜？點樣檢查？仲有邊啲地方唔確定？","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-12.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/audio/yue-HK/page-12.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-12-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-12-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1/media/12-zh-Hant.png","name":"一個好問題，帶來更多問題；當 AI 給出答案，我們可以問：怎樣檢查？"},{"type":"shape","id":"nobel08-slide-12-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-12-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-12-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"哈薩比斯嘅故事連結咗遊戲開發、不同學科嘅學習同團隊合作。獲獎進展幫更多研究者探索生命入面嘅小工具。下次見到人工智能畀出漂亮答案，可以問：根據係乜？點樣檢查？仲有邊啲地方唔確定？"},"script":"哈薩比斯嘅故事連結咗遊戲開發、不同學科嘅學習同團隊合作。獲獎進展幫更多研究者探索生命入面嘅小工具。下次見到人工智能畀出漂亮答案，可以問：根據係乜？點樣檢查？仲有邊啲地方唔確定？"}}]},"hk-nobel-08-hassabis-illustrated-v1-mandarin":{"id":"hk-nobel-08-hassabis-illustrated-v1-mandarin","createdAt":"2026-11-04T00:00:00.000Z","stage":{"id":"hk-nobel-08-hassabis-illustrated-v1-mandarin","name":"諾貝爾科學故事 08：哈薩比斯與蛋白質預測（普通話）","description":"從遊戲到生命科學，認識人工智能如何幫助研究蛋白質，與日常生活有甚麼關係。","languageDirective":"使用香港繁體中文，以普通話向初中學生講授。明確區分計算預測、實驗證據和仍待驗證的應用；不提供醫療建議。","createdAt":1793793600000,"updatedAt":1793793600000,"style":"slide","generatedAgentConfigs":[{"id":"nobel08-teacher","name":"科學故事老師","role":"teacher","persona":"我用香港生活例子講解蛋白質結構預測及其價值，說明類比限制，不把研究前景說成已有療效。","avatar":"/avatars/teacher.png","color":"#24665f","priority":10},{"id":"nobel08-assistant","name":"科學小助手","role":"assistant","persona":"我幫學生區分計算模型、實驗證據和研究前景，尊重不確定性，不提供個人診療。","avatar":"/avatars/assist.png","color":"#2563eb","priority":7},{"id":"nobel08-student","name":"好奇同學","role":"student","persona":"我是AI同學，喜歡提出簡短問題，幫助大家思考如何檢查證據。","avatar":"/avatars/curious.png","color":"#bf9949","priority":5}]},"scenes":[{"id":"nobel08-slide-01","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"德米斯・哈薩比斯","order":1,"outlineId":"nobel08-slide-01-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"interactive","actions":[{"id":"nobel08-slide-01-speech","type":"speech","text":"照片里的人叫哈薩比斯。他參與過遊戲開發，學過計算機科學，也接受過腦科學研究訓練。他的研究經歷里，有下圍棋的AI，也有幫助研究生命的AI。今天，我們不比誰能背出最多專業名詞，只跟著他問一個問題：電腦能不能幫助科學家，知道身體里一些極小的“工具”長什麼樣？","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-01.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-01.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>*{box-sizing:border-box}html,body{margin:0;background:#f6f1e6;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}.slide{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden}.background{display:block;width:100%;height:100%;object-fit:fill}.portrait{position:absolute;left:68.6%;top:17.8%;width:22.5%;height:51.4%;object-fit:contain}.caption{position:absolute;left:62%;top:71%;width:34.5%;color:#31515a;font-size:clamp(10px,1vw,13px);line-height:1.25}.voice{position:absolute;left:62%;top:85%;font-size:clamp(15px,1.5vw,20px)}.footer{position:absolute;left:4%;bottom:1.5%;width:92%;padding:.4%;background:#f5f0e8;color:#31515a;font-size:clamp(10px,1vw,13px)}.mobile-title{display:none}a{color:#24665f}html.phone .background{opacity:.14}html.phone .mobile-title{display:block;position:absolute;left:4%;top:5%;width:59%;font-size:60px;line-height:1.15;font-weight:800}html.phone .mobile-title span{display:block;font-size:46px;margin-top:16px}html.phone .portrait{left:68%;top:6%;width:27%;height:56%}html.phone .caption{display:none}.mobile-credit{display:none}html.phone .mobile-credit{display:block;position:absolute;left:4%;top:63%;width:58%;font-size:38px;line-height:1.15;color:#31515a}html.phone .voice{left:64%;top:73%;font-size:50px;font-weight:700}html.phone .footer{font-size:25px}</style><script>if(Math.min(screen.width,screen.height)<=500)document.documentElement.classList.add('phone')</script><div class=\"slide\"><img class=\"background\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/01-zh-Hant.png\" alt=\"德米斯・哈薩比斯：從遊戲世界，到研究生命的小工具。2024年諾貝爾化學獎共同得主。\"><div class=\"mobile-title\">德米斯・哈薩比斯<span>從遊戲世界，到研究生命的小工具<br>2024年諾貝爾化學獎共同得主</span></div><img class=\"portrait\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/hassabis-portrait.jpg\" alt=\"德米斯・哈薩比斯資料肖像\"><div class=\"caption\">德米斯・哈薩比斯，2018年資料照。The Royal Society，經裁剪，<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://commons.wikimedia.org/wiki/File:Demis_Hassabis_Royal_Society_(cropped).jpg\">來源及授權</a>（CC BY-SA 4.0／原圖 CC BY-SA 3.0）。</div><div class=\"mobile-credit\">肖像：The Royal Society，2018，經裁剪<br><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://commons.wikimedia.org/wiki/File:Demis_Hassabis_Royal_Society_(cropped).jpg\">來源及授權</a>：CC BY-SA 4.0／原圖 3.0</div><a class=\"voice\" href=\"/classroom/hk-nobel-08-hassabis-illustrated-v1\" target=\"_blank\" rel=\"noopener noreferrer\">切換至廣東話講解 →</a><div class=\"footer\">教學插畫為示意，並非研究現場。 <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></div></div></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel08-slide-02","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"同一張紙，形狀改變了甚麼？","order":2,"outlineId":"nobel08-slide-02-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"interactive","actions":[{"id":"nobel08-slide-02-speech","type":"speech","text":"想象桌上有幾枚回形針。紙平鋪著，很容易讓回形針滑到旁邊；折成一個合適的小紙盒，就更方便裝著它們。紙的形狀改變了，用途也會改變。生命中的許多小工具，形狀也與它們怎樣工作有關。這個比方只說明“形狀很重要”：蛋白質不是細胞里的小人折出來的紙盒，它們靠分子間的作用，在一定環境中形成結構。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-02.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-02.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>html,body{margin:0;background:#f5f0e8;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}main{max-width:1080px;margin:auto;padding:12px 20px}.art{display:block;width:100%;max-height:47vh;object-fit:contain}.question{border:2px solid #b5d4c5;background:#fffaf0;border-radius:18px;padding:14px 20px}h2{font-size:clamp(18px,2.3vw,27px);margin:0 0 10px}.options{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;font-size:clamp(16px,1.7vw,22px);border:2px solid #368471;border-radius:10px;padding:10px 16px;background:#fff}button[aria-pressed=true]{background:#b5e5cf}.feedback{font-size:17px;line-height:1.5;min-height:2em}.note{font-size:13px;color:#47616c}html.phone .art{max-height:8vh}html.phone .question{padding:8px 14px}html.phone h2{font-size:52px}html.phone button{font-size:56px;padding:40px 28px}html.phone .feedback{font-size:40px;margin:8px 0;min-height:0}html.phone .note{font-size:50px;margin:3px 0}</style><script>if(Math.min(screen.width,screen.height)<=500)document.documentElement.classList.add('phone')</script><main><img class=\"art\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/02-zh-Hant.png\" alt=\"一張紙與摺成的紙盒，用來比喻形狀與用途的關係\"><section class=\"question\"><h2>要用紙盛載萬字夾，哪一種形狀通常比較方便？</h2><div class=\"options\"><button data-choice=\"0\" aria-pressed=\"false\">平放的紙</button><button data-choice=\"1\" aria-pressed=\"false\">摺成合適的小紙盒</button></div><p class=\"feedback\" id=\"feedback\" aria-live=\"polite\"></p></section><p class=\"note\">生活類比：形狀可能影響用途；蛋白質不是紙盒。可以重新選擇。</p></main><script>document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('feedback').textContent=b.dataset.choice==='1'?'對，合適的小紙盒較容易盛載。形狀有時影響用途，蛋白質則不是紙盒。':'平放的紙較難擋住萬字夾滑落；試試另一種形狀。這只是生活類比。'})</script></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel08-slide-03","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"身體裏的小工具","order":3,"outlineId":"nobel08-slide-03-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-03-focus","type":"spotlight","elementId":"nobel08-slide-03-key"},{"id":"nobel08-slide-03-speech","type":"speech","text":"你可能在牛奶或餅乾包裝上見過“蛋白質”。身體里的蛋白質也參與著許多不同工作。例如，有些幫助化學反應進行，有些參與傳遞信號。它們並不是同一種固定的小零件。今天不用記住每一種名字，只需要知道：科學家想弄清這些東西怎樣工作，形狀是重要線索之一。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-03.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-03.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-03-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-03-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/03-zh-Hant.png","name":"身體裏的小工具；許多蛋白質參與身體的不同工作。"},{"type":"shape","id":"nobel08-slide-03-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-03-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-03-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"你可能在牛奶或餅乾包裝上見過“蛋白質”。身體里的蛋白質也參與著許多不同工作。例如，有些幫助化學反應進行，有些參與傳遞信號。它們並不是同一種固定的小零件。今天不用記住每一種名字，只需要知道：科學家想弄清這些東西怎樣工作，形狀是重要線索之一。"},"script":"你可能在牛奶或餅乾包裝上見過“蛋白質”。身體里的蛋白質也參與著許多不同工作。例如，有些幫助化學反應進行，有些參與傳遞信號。它們並不是同一種固定的小零件。今天不用記住每一種名字，只需要知道：科學家想弄清這些東西怎樣工作，形狀是重要線索之一。"}},{"id":"nobel08-slide-04","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"順序表，還不是立體圖","order":4,"outlineId":"nobel08-slide-04-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-04-focus","type":"spotlight","elementId":"nobel08-slide-04-key"},{"id":"nobel08-slide-04-speech","type":"speech","text":"許多蛋白質可以先想象成一條由小零件連接起來的鏈，這些小零件叫氨基酸。科學家能用字母記下它們的順序。長長的鏈有很多彎折、靠近的可能，真實分子的作用又會限制形狀。可是，光看這串字母，並不能直接看見整條鏈在空間中怎樣彎折、哪些部分靠近。你可以把“順序表”和“立體圖”並排看：前者告訴我們排列線索，後者幫助我們研究空間里的關係。真實蛋白質還會受環境影響，也可能活動，不是一根永遠僵硬的塑料繩。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-04.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-04.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-04-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-04-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/04-zh-Hant.png","name":"順序表，還不是立體圖；知道小零件的順序，還要研究它在空間的形狀。"},{"type":"shape","id":"nobel08-slide-04-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-04-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-04-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"許多蛋白質可以先想象成一條由小零件連接起來的鏈，這些小零件叫氨基酸。科學家能用字母記下它們的順序。長長的鏈有很多彎折、靠近的可能，真實分子的作用又會限制形狀。可是，光看這串字母，並不能直接看見整條鏈在空間中怎樣彎折、哪些部分靠近。你可以把“順序表”和“立體圖”並排看：前者告訴我們排列線索，後者幫助我們研究空間里的關係。真實蛋白質還會受環境影響，也可能活動，不是一根永遠僵硬的塑料繩。"},"script":"許多蛋白質可以先想象成一條由小零件連接起來的鏈，這些小零件叫氨基酸。科學家能用字母記下它們的順序。長長的鏈有很多彎折、靠近的可能，真實分子的作用又會限制形狀。可是，光看這串字母，並不能直接看見整條鏈在空間中怎樣彎折、哪些部分靠近。你可以把“順序表”和“立體圖”並排看：前者告訴我們排列線索，後者幫助我們研究空間里的關係。真實蛋白質還會受環境影響，也可能活動，不是一根永遠僵硬的塑料繩。"}},{"id":"nobel08-slide-05","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"為甚麼他想研究這個難題？","order":5,"outlineId":"nobel08-slide-05-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-05-focus","type":"spotlight","elementId":"nobel08-slide-05-key"},{"id":"nobel08-slide-05-speech","type":"speech","text":"哈薩比斯在自己的回顧中談到，AI在棋盤上取得進展後，他想把技術用於加快科學發現。預測蛋白質形狀，是團隊選擇的重要難題。下棋的程序和預測蛋白質的程序並不是同一個系統；研究者需要重新學習問題、設計方法，並與不同專業的人合作。這個故事有意思的地方，是把一個領域學到的本領，帶去面對另一個真正需要解決的問題。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-05.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-05.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-05-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-05-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/05-zh-Hant.png","name":"為甚麼他想研究這個難題？；將人工智能帶到科學問題，需要不同專業合作。"},{"type":"shape","id":"nobel08-slide-05-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-05-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-05-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"哈薩比斯在自己的回顧中談到，AI在棋盤上取得進展後，他想把技術用於加快科學發現。預測蛋白質形狀，是團隊選擇的重要難題。下棋的程序和預測蛋白質的程序並不是同一個系統；研究者需要重新學習問題、設計方法，並與不同專業的人合作。這個故事有意思的地方，是把一個領域學到的本領，帶去面對另一個真正需要解決的問題。"},"script":"哈薩比斯在自己的回顧中談到，AI在棋盤上取得進展後，他想把技術用於加快科學發現。預測蛋白質形狀，是團隊選擇的重要難題。下棋的程序和預測蛋白質的程序並不是同一個系統；研究者需要重新學習問題、設計方法，並與不同專業的人合作。這個故事有意思的地方，是把一個領域學到的本領，帶去面對另一個真正需要解決的問題。"}},{"id":"nobel08-slide-06","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"AI 幫忙做甚麼？","order":6,"outlineId":"nobel08-slide-06-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-06-focus","type":"spotlight","elementId":"nobel08-slide-06-key"},{"id":"nobel08-slide-06-speech","type":"speech","text":"研究者以前用實驗積累了許多蛋白質結構資料，這些資料是AI學習的重要基礎。哈薩比斯、約翰·江珀和團隊開發的AlphaFold系統，把蛋白質的序列等線索用於結構預測。我們今天只抓住這一步：輸入線索，得到一個可以進一步檢查的立體模型。AI並沒有拿著相機鑽進細胞；它輸出的是計算預測，也不等於已經解釋了蛋白質工作的每一個過程。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-06.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-06.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-06-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-06-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/06-zh-Hant.png","name":"AI 幫忙做甚麼？；利用已知資料與序列等線索，預測蛋白質的形狀。"},{"type":"shape","id":"nobel08-slide-06-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-06-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-06-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"研究者以前用實驗積累了許多蛋白質結構資料，這些資料是AI學習的重要基礎。哈薩比斯、約翰·江珀和團隊開發的AlphaFold系統，把蛋白質的序列等線索用於結構預測。我們今天只抓住這一步：輸入線索，得到一個可以進一步檢查的立體模型。AI並沒有拿著相機鑽進細胞；它輸出的是計算預測，也不等於已經解釋了蛋白質工作的每一個過程。"},"script":"研究者以前用實驗積累了許多蛋白質結構資料，這些資料是AI學習的重要基礎。哈薩比斯、約翰·江珀和團隊開發的AlphaFold系統，把蛋白質的序列等線索用於結構預測。我們今天只抓住這一步：輸入線索，得到一個可以進一步檢查的立體模型。AI並沒有拿著相機鑽進細胞；它輸出的是計算預測，也不等於已經解釋了蛋白質工作的每一個過程。"}},{"id":"nobel08-slide-07","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"怎樣知道預測不是瞎猜？","order":7,"outlineId":"nobel08-slide-07-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"interactive","actions":[{"id":"nobel08-slide-07-speech","type":"speech","text":"在一次重要評估中，研究者先提交預測，再與尚未公開的實驗結構比較。這就像先交答案，再揭開核對依據，能幫助我們判斷方法有沒有真正的本領。2020年，AlphaFold2在這樣的評估中取得重要進展。請看資料圖：預測與實驗得到的結構模型可以作比較。這一個例子不能代表每一次都同樣準確；科學判斷需要看更多評估和不確定的地方。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-07.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-07.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>*{box-sizing:border-box}html,body{margin:0;background:#f6f1e6;font-family:system-ui,\"PingFang HK\",sans-serif}.slide{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden}.background{display:block;width:100%;height:100%;object-fit:fill}.figure{position:absolute;left:61%;top:27%;width:31.5%;height:44.8%;overflow:hidden;background:white}.figure img{position:absolute;max-width:none;width:406.981%;height:auto;left:-102.83%;top:-21.176%}.caption{position:absolute;left:61%;top:74%;width:34%;color:#31515a;font-size:clamp(8px,1.1vw,14px);line-height:1.3}.footer{position:absolute;left:4%;bottom:1.5%;width:92%;padding:.4%;background:#f5f0e8;color:#31515a;font-size:clamp(8px,1vw,13px)}a{color:#245f5a}.mobile-heading{display:none}html.phone .background{opacity:.13}html.phone .mobile-heading{display:block;position:absolute;left:4%;top:8%;width:38%;font-size:58px;font-weight:800;line-height:1.25;color:#102b38}html.phone .figure{left:56%;top:4%;width:40%;height:57%}html.phone .caption{left:4%;top:66%;width:92%;font-size:50px;line-height:1.1}html.phone .footer{display:none}</style><script>if(Math.min(screen.width,screen.height)<=500)document.documentElement.classList.add('phone')</script><div class=\"slide\"><img class=\"background\" src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/07-zh-Hant.png\" alt=\"怎樣知道預測不是瞎猜？先交預測，再和實驗得到的結構比較。\"><div class=\"mobile-heading\">怎樣知道預測不是瞎猜？</div><div class=\"figure\"><img src=\"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/alphafold-paper-figure-1.png\" alt=\"論文圖1b局部，藍色預測與綠色實驗結構模型的對照\"></div><div class=\"caption\">藍：預測；綠：實驗模型。不是照片。Jumper 等，Nature（2021）圖1b；<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nature.com/articles/s41586-021-03819-2\">論文及完整圖</a>／<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>。</div><div class=\"footer\">教學插畫為示意，並非研究現場。 <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></div></div></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel08-slide-08","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"為甚麼值得諾貝爾獎？","order":8,"outlineId":"nobel08-slide-08-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-08-focus","type":"spotlight","elementId":"nobel08-slide-08-key"},{"id":"nobel08-slide-08-speech","type":"speech","text":"蛋白質的結構預測，是科學家長期面對的難題。哈薩比斯和江珀與團隊取得的進展，讓研究者更有辦法獲得、檢查和利用結構線索。這是他們在2024年共同獲得諾貝爾化學獎的重要原因。同年，戴維·貝克因計算蛋白質設計獲得另一部分獎項。預測已有蛋白質的形狀，與設計新的蛋白質，是有關聯但不相同的工作。我們的故事聚焦哈薩比斯，也要記住同伴和先前研究的貢獻。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-08.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-08.mp3"},{"id":"nobel08-slide-08-discussion","type":"discussion","agentId":"nobel08-assistant","topic":"蛋白質結構預測為甚麼有價值？我們還需要怎樣檢查？","prompt":"簡短課堂討論。科學小助手先解釋預測模型不等於實驗照片；科學故事老師連回研究工具的價值；AI同學提出一個與證據有關的追問。各人只說自己的話，然後交回學生，不延伸新回合。不提供個人醫療建議。"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-08-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-08-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/08-zh-Hant.png","name":"為甚麼值得諾貝爾獎？；研究者多了一種探索蛋白質結構的重要工具。"},{"type":"shape","id":"nobel08-slide-08-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-08-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-08-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"蛋白質的結構預測，是科學家長期面對的難題。哈薩比斯和江珀與團隊取得的進展，讓研究者更有辦法獲得、檢查和利用結構線索。這是他們在2024年共同獲得諾貝爾化學獎的重要原因。同年，戴維·貝克因計算蛋白質設計獲得另一部分獎項。預測已有蛋白質的形狀，與設計新的蛋白質，是有關聯但不相同的工作。我們的故事聚焦哈薩比斯，也要記住同伴和先前研究的貢獻。"},"script":"蛋白質的結構預測，是科學家長期面對的難題。哈薩比斯和江珀與團隊取得的進展，讓研究者更有辦法獲得、檢查和利用結構線索。這是他們在2024年共同獲得諾貝爾化學獎的重要原因。同年，戴維·貝克因計算蛋白質設計獲得另一部分獎項。預測已有蛋白質的形狀，與設計新的蛋白質，是有關聯但不相同的工作。我們的故事聚焦哈薩比斯，也要記住同伴和先前研究的貢獻。"}},{"id":"nobel08-slide-09","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"飲料瓶與科學有甚麼關係？","order":9,"outlineId":"nobel08-slide-09-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-09-focus","type":"spotlight","elementId":"nobel08-slide-09-key"},{"id":"nobel08-slide-09-speech","type":"speech","text":"你每天會碰到塑料包裝。研究者也在研究與分解塑料有關的酶；酶是一類能幫助化學反應進行的分子，其中許多是蛋白質。結構線索可以幫助他們提出更具體的問題：哪些部位可能參與工作？怎樣再用實驗檢查？這是一種研究價值。它並不等於已經有一種萬能辦法，能讓所有塑料在任何條件下迅速消失。處理哪種材料、需要什麼條件、效果怎樣，都要分別驗證。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-09.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-09.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-09-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-09-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/09-zh-Hant.png","name":"飲料瓶與科學有甚麼關係？；研究某些酶的形狀，可能幫助科學家研究材料處理。"},{"type":"shape","id":"nobel08-slide-09-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-09-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-09-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"你每天會碰到塑料包裝。研究者也在研究與分解塑料有關的酶；酶是一類能幫助化學反應進行的分子，其中許多是蛋白質。結構線索可以幫助他們提出更具體的問題：哪些部位可能參與工作？怎樣再用實驗檢查？這是一種研究價值。它並不等於已經有一種萬能辦法，能讓所有塑料在任何條件下迅速消失。處理哪種材料、需要什麼條件、效果怎樣，都要分別驗證。"},"script":"你每天會碰到塑料包裝。研究者也在研究與分解塑料有關的酶；酶是一類能幫助化學反應進行的分子，其中許多是蛋白質。結構線索可以幫助他們提出更具體的問題：哪些部位可能參與工作？怎樣再用實驗檢查？這是一種研究價值。它並不等於已經有一種萬能辦法，能讓所有塑料在任何條件下迅速消失。處理哪種材料、需要什麼條件、效果怎樣，都要分別驗證。"}},{"id":"nobel08-slide-10","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"離新藥，還有多遠？","order":10,"outlineId":"nobel08-slide-10-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-10-focus","type":"spotlight","elementId":"nobel08-slide-10-key"},{"id":"nobel08-slide-10-speech","type":"speech","text":"對普通人來說，我們希望科學家能更好理解疾病，也希望未來有更安全有效的治療辦法。結構預測可以幫助研究者思考蛋白質怎樣工作、哪些問題值得實驗檢驗。但從一個結構模型，走到一種對病人安全有效的藥物，中間還有許多檢驗。今天記住的價值是：研究者多了一種有用的工具；新的治療是否有效，仍要靠證據。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-10.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-10.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-10-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-10-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/10-zh-Hant.png","name":"離新藥，還有多遠？；預測提供研究線索；安全和效果仍要經過檢驗。"},{"type":"shape","id":"nobel08-slide-10-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-10-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-10-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"對普通人來說，我們希望科學家能更好理解疾病，也希望未來有更安全有效的治療辦法。結構預測可以幫助研究者思考蛋白質怎樣工作、哪些問題值得實驗檢驗。但從一個結構模型，走到一種對病人安全有效的藥物，中間還有許多檢驗。今天記住的價值是：研究者多了一種有用的工具；新的治療是否有效，仍要靠證據。"},"script":"對普通人來說，我們希望科學家能更好理解疾病，也希望未來有更安全有效的治療辦法。結構預測可以幫助研究者思考蛋白質怎樣工作、哪些問題值得實驗檢驗。但從一個結構模型，走到一種對病人安全有效的藥物，中間還有許多檢驗。今天記住的價值是：研究者多了一種有用的工具；新的治療是否有效，仍要靠證據。"}},{"id":"nobel08-slide-11","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"三次小判斷","order":11,"outlineId":"nobel08-slide-11-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"quiz","actions":[{"id":"nobel08-slide-11-speech","type":"speech","text":"現在停一下，判斷三個問題。可以重新選擇，看一看解釋，再用自己的話說說：這項研究為什麼重要？","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-11.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-11.mp3"}],"content":{"type":"quiz","questions":[{"id":"nobel08-slide-11-q1","type":"single","question":"1. 只知道蛋白質小零件的連接順序，是否就已直接看到完整立體形狀？","options":[{"value":"A","label":"是，順序表就是立體圖"},{"value":"B","label":"還需要進一步研究或預測"}],"answer":["B"],"analysis":"A：順序提供線索，但順序表和立體圖不同。；B：正確，還需要研究或預測空間關係。","points":10,"hasAnswer":true},{"id":"nobel08-slide-11-q2","type":"single","question":"2. AI 給出結構預測圖，是否等於拍了一張分子照片？","options":[{"value":"A","label":"是，圖漂亮就是實拍"},{"value":"B","label":"不是，它是需要檢查的模型"}],"answer":["B"],"analysis":"A：圖漂亮不代表實拍。；B：正確，這是計算預測，需要查核與評估不確定性。","points":10,"hasAnswer":true},{"id":"nobel08-slide-11-q3","type":"single","question":"3. 一項研究為尋找新藥提供線索，接下來可以怎樣說？","options":[{"value":"A","label":"已證明某種藥可以治病"},{"value":"B","label":"有了可繼續檢驗的方向"}],"answer":["B"],"analysis":"A：研究線索並不是療效證明。；B：正確，是否安全有效仍需後續研究。","points":10,"hasAnswer":true}]}},{"id":"nobel08-slide-12","stageId":"hk-nobel-08-hassabis-illustrated-v1-mandarin","title":"一個好問題，帶來更多問題","order":12,"outlineId":"nobel08-slide-12-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel08-slide-12-focus","type":"spotlight","elementId":"nobel08-slide-12-key"},{"id":"nobel08-slide-12-speech","type":"speech","text":"哈薩比斯的故事連接著遊戲開發、不同學科的學習和團隊合作。諾貝爾獎獎勵的這項進展，讓許多研究者更有辦法探索生命中的小工具。下次看到AI給出一個很漂亮的答案，你可以問：它依據什麼？怎樣檢查？哪裏還不能確定？帶著這些問題，好奇心就不只是“哇，好厲害”，還會變成認真理解世界的起點。","audioId":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-12.mp3","audioUrl":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/audio/zh-CN/page-12.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel08-slide-12-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel08-slide-12-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1-mandarin/media/12-zh-Hant.png","name":"一個好問題，帶來更多問題；當 AI 給出答案，我們可以問：怎樣檢查？"},{"type":"shape","id":"nobel08-slide-12-key","left":40,"top":90,"width":460,"height":190,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel08-slide-12-footer","left":40,"top":521,"width":920,"height":32,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel08-slide-12-boundary","left":44,"top":525,"width":910,"height":24,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.25\">教學插畫為示意，並非研究現場。 <a href=\"https://www.nobelprize.org/prizes/chemistry/2024/press-release/\">諾貝爾獎資料</a></p>","defaultColor":"#31515a","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"哈薩比斯的故事連接著遊戲開發、不同學科的學習和團隊合作。諾貝爾獎獎勵的這項進展，讓許多研究者更有辦法探索生命中的小工具。下次看到AI給出一個很漂亮的答案，你可以問：它依據什麼？怎樣檢查？哪裏還不能確定？帶著這些問題，好奇心就不只是“哇，好厲害”，還會變成認真理解世界的起點。"},"script":"哈薩比斯的故事連接著遊戲開發、不同學科的學習和團隊合作。諾貝爾獎獎勵的這項進展，讓許多研究者更有辦法探索生命中的小工具。下次看到AI給出一個很漂亮的答案，你可以問：它依據什麼？怎樣檢查？哪裏還不能確定？帶著這些問題，好奇心就不只是“哇，好厲害”，還會變成認真理解世界的起點。"}}]}},base='https://class.wanli.ai',cid='hk-nobel-08-hassabis-illustrated-v1',out='artifacts/nobel08';await fs.mkdir(out,{recursive:true});const b=await chromium.launch(),result={pass:false,cases:[]};let last;
try{for(const spec of [{name:'desktop-yue',suffix:'',viewport:{width:1440,height:900}},{name:'desktop-mandarin',suffix:'-mandarin',viewport:{width:1440,height:900}},{name:'mobile-yue',suffix:'',viewport:{width:390,height:844}},{name:'mobile-mandarin',suffix:'-mandarin',viewport:{width:390,height:844}}]){const ctx=await b.newContext({viewport:spec.viewport,locale:'zh-HK',...(spec.name.startsWith('mobile-')?{isMobile:true,hasTouch:true,screen:{width:390,height:844}}:{})});await ctx.route('**/api/classroom?id=*',route=>{const id=new URL(route.request().url()).searchParams.get('id');return candidates[id]?route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({success:true,classroom:candidates[id]})}):route.continue()});await ctx.route('**/api/classroom-media/hk-nobel-08-hassabis-illustrated-v1*/**',route=>{const u=new URL(route.request().url());u.pathname=u.pathname.replace(/\/hk-nobel-08-hassabis-illustrated-v1(?:-mandarin)?\//,'/nobel08-figure-check-7c2f12/');return route.continue({url:u.toString()})});const p=await ctx.newPage();last=p;await p.goto(base+'/classroom/'+cid+spec.suffix);const frame=p.frameLocator('iframe:visible').first();const img=frame.locator('img.background');await img.waitFor({timeout:60000});await img.evaluate(e=>e.decode());const portrait=frame.locator('img.portrait');await portrait.waitFor();await portrait.evaluate(e=>e.decode());if(spec.name.startsWith('mobile-'))assert.equal(await frame.locator('html').getAttribute('class'),'phone');await p.waitForTimeout(1000);await p.screenshot({path:out+'/'+spec.name+'-01.png',fullPage:true});const popupWait=ctx.waitForEvent('page',{timeout:10000});await frame.locator('a.voice').click();const popup=await popupWait;await popup.waitForURL('**/'+cid+(spec.suffix?'':'-mandarin'));await popup.close();result.cases.push({name:spec.name+'-voice-link',pass:true});await p.getByRole('button',{name:'Next scene',exact:true}).first().click();const f=p.frameLocator('iframe:visible').first();await f.locator('img.art').waitFor();await f.locator('img.art').evaluate(e=>e.decode());await f.locator('button[data-choice="0"]').click();await p.screenshot({path:out+'/'+spec.name+'-02-wrong.png',fullPage:true});await f.locator('button[data-choice="1"]').click();assert.match(await f.locator('#feedback').innerText(),/對/);if(spec.name.startsWith('mobile-')){const note=f.locator('.note');const n=await note.evaluate(e=>({font:parseFloat(getComputedStyle(e).fontSize),width:e.getBoundingClientRect().width,bottom:e.getBoundingClientRect().bottom,view:innerHeight}));const nb=await note.boundingBox();const button=await f.locator('button[data-choice="1"]').boundingBox();const px=n.font*nb.width/n.width;assert.ok(px>=14,`note rendered ${px}px`);assert.ok(n.bottom<=n.view,`note clipped ${n.bottom}/${n.view}`);assert.ok(button.height>=44,`button height ${button.height}`);result.cases.push({name:spec.name+'-readability',notePx:px,buttonHeight:button.height})}await p.waitForTimeout(1000);await p.screenshot({path:out+'/'+spec.name+'-02.png',fullPage:true});if(spec.name==='mobile-yue'){for(let n=3;n<=10;n++){await p.getByRole('button',{name:'Next scene',exact:true}).first().click();await p.waitForTimeout(400);if(n===7){const pic=p.frameLocator('iframe:visible').first().locator('.figure img');await pic.waitFor();await pic.evaluate(e=>e.decode());const cap=p.frameLocator('iframe:visible').first().locator('.caption');const cc=await cap.evaluate(e=>({font:parseFloat(getComputedStyle(e).fontSize),width:e.getBoundingClientRect().width,bottom:e.getBoundingClientRect().bottom,view:innerHeight}));const bb=await cap.boundingBox();const px=cc.font*bb.width/cc.width;assert.ok(px>=14,`figure legend rendered ${px}px`);assert.ok(cc.bottom<=cc.view,`figure caption clipped ${cc.bottom}/${cc.view}`);result.cases.push({name:'mobile-figure-caption',renderedPx:px})}else{const pic=p.locator(`img[src*="${String(n).padStart(2,'0')}-zh-Hant.png"]:visible`).first();await pic.waitFor();await pic.evaluate(e=>e.decode())}await p.screenshot({path:out+`/mobile-yue-${String(n).padStart(2,'0')}.png`,fullPage:true})}}result.cases.push({name:spec.name,artDecoded:true,portraitDecoded:true,interactionRetry:true});await ctx.close()}result.pass=true}catch(e){result.failure=String(e);if(last&&!last.isClosed())await last.screenshot({path:out+'/failure.png',fullPage:true}).catch(()=>{});throw e}finally{await b.close();await fs.writeFile(out+'/layout.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result))}
